SINA_SMART["anat1-thorax-myology"] = {"lecture":"anat1-thorax-myology","title":"Thorax part 3: myology","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat1-thorax-myology:e5","text":"Diaphragm: principal respiratory muscle; flattens on contraction.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-myology:e0","text":"Pectoralis major: flexion, adduction, medial rotation of humerus.","topic":"Anterior, lateral and back muscles","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-myology:e1","text":"Pectoralis minor (ribs 3-5 → coracoid), subclavius: accessory inspiratory muscles.","topic":"Anterior, lateral and back muscles","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-myology:e2","text":"Serratus anterior (ribs 1-8): protracts scapula.","topic":"Anterior, lateral and back muscles","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-myology:e3","text":"Intercostal nerves/vessels between 2nd and 3rd layers.","topic":"Intercostal muscles","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-myology:e4","text":"External intercostals raise ribs (inspiration); internal lower them (expiration).","topic":"Intercostal muscles","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-myology:e6","text":"Origins: crura (R L1-L3, L L1-L2), lower 6 ribs, xiphoid.","topic":"Diaphragm","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-myology:e7","text":"Phrenic nerve C3-C5: motor and sensory.","topic":"Diaphragm","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat1-thorax-myology:e8","text":"Openings: IVC T8, oesophagus T10, aorta T12.","topic":"Diaphragm","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"c76dfk":"a","1jlidy3":"a","xsfj40":"a","1h3rbp4":"a","y3xoov":"a","jmy58m":"a","1m7sq3":"a","iypekm":"a","zgc86b":"a","1vcrwnt":"a","1f53jmg":"a","ld2jri":"a"},"mapCounts":{"verified":0,"auto":12,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat1-thorax-myology:e5":{"s":0,"u":["Diaphragm: principal respiratory muscle; flattens on contraction.","The thoracic muscles move the upper limb and scapula, fill the intercostal spaces, and power breathing through the diaphragm , the principal muscle of respiration."],"dp":[]},"anat1-thorax-myology:e0":{"s":1,"u":["Pectoralis major: flexion, adduction, medial rotation of humerus.","Anterior wall : pectoralis major (sternum, clavicle, costal margin → bicipital groove; flexes, adducts and medially rotates the humerus), pectoralis minor (ribs 3-5 → coracoid; stabilises the scapula), subclavius (clavicle ↔ rib 1; depresses the clavicle); all serve as accessory muscles of deep inspiration ."],"dp":[]},"anat1-thorax-myology:e1":{"s":1,"u":["Pectoralis minor (ribs 3-5 → coracoid), subclavius: accessory inspiratory muscles.","Anterior wall : pectoralis major (sternum, clavicle, costal margin → bicipital groove; flexes, adducts and medially rotates the humerus), pectoralis minor (ribs 3-5 → coracoid; stabilises the scapula), subclavius (clavicle ↔ rib 1; depresses the clavicle); all serve as accessory muscles of deep inspiration ."],"dp":[{"h":"Note","t":"The right crus is longer (L1-L3) than the left (L1-L2), and its fibres encircle the oesophageal hiatus. Accessory inspiratory muscles: SCM, scalenes, pectorals."}]},"anat1-thorax-myology:e2":{"s":1,"u":["Serratus anterior (ribs 1-8): protracts scapula.","Lateral wall : serratus anterior (ribs 1-8 → medial border of scapula; protracts and stabilises the scapula)."],"dp":[]},"anat1-thorax-myology:e3":{"s":2,"u":["Intercostal nerves/vessels between 2nd and 3rd layers.","Eleven intercostal spaces, each with three layers; the intercostal nerves and vessels run between the second and third layers."],"dp":[{"h":"Note","t":"The neurovascular bundle runs between the internal and innermost intercostals (2nd and 3rd layers)."}]},"anat1-thorax-myology:e4":{"s":2,"u":["External intercostals raise ribs (inspiration); internal lower them (expiration).","External intercostals (superficial; fibres downward and forward, from the rib tubercles to the costochondral joints, then the external intercostal membrane): raise the ribs → inspiration .","Internal intercostals (middle; fibres at right angles, from the sternum to the rib angles, then the internal intercostal membrane): lower the ribs → expiration ."],"dp":[{"h":"Note","t":"External intercostals (down and forward, 'hands in pockets') raise the ribs → inspiration . Internal intercostals lower them → forced expiration ."}]},"anat1-thorax-myology:e6":{"s":3,"u":["Origins: crura (R L1-L3, L L1-L2), lower 6 ribs, xiphoid.","Origins : lumbar (right crus from L1-L3, left crus from L1-L2), costal (inner surfaces of the lower six ribs), sternal (back of the xiphoid)."],"dp":[]},"anat1-thorax-myology:e7":{"s":3,"u":["Phrenic nerve C3-C5: motor and sensory.","Innervation : the phrenic nerves (C3, C4, C5) , motor, and sensory to the central diaphragm, pericardium, mediastinal and diaphragmatic pleura; they run on the anterior scalene, enter between subclavian vein and artery, and descend in front of the lung roots between the mediastinal pleura and pericardium with the pericardiacophrenic vessels."],"dp":[{"h":"Why diaphragm pain is felt in the shoulder","t":"The phrenic nerve carries sensation from the central diaphragm and comes from the C3-C5 segments, which also supply the skin over the shoulder. Irritation under the diaphragm, from blood, pus or an inflamed gallbladder, is therefore felt as shoulder-tip pain: a classic referred pain. Source: the lecture's diaphragm innervation slide."},{"h":"Note","t":"Diaphragm = main inspiratory muscle; contraction flattens it. Phrenic nerve C3-C5 ('C3, 4, 5 keeps the diaphragm alive'): motor + sensory to the central part."}]},"anat1-thorax-myology:e8":{"s":3,"u":["Openings: IVC T8, oesophagus T10, aorta T12.","Openings : caval (T8) , in the central tendon right of midline: inferior vena cava; oesophageal (T10) : oesophagus and vagal trunks; aortic (T12) : aorta, thoracic duct (azygos vein)."],"dp":[{"h":"Note","t":"Diaphragm openings : caval T8 (central tendon, with the right phrenic nerve), oesophageal T10 (vagal trunks), aortic T12 (behind the median arcuate ligament, with the thoracic duct and azygos)."}]}},"meta":{"c76dfk":{"a":"recall","vg":"anat1-thorax-myology:e1/recall/1"},"1jlidy3":{"a":"recall","vg":"anat1-thorax-myology:e2/recall/1"},"xsfj40":{"a":"relationship","vg":"anat1-thorax-myology:e3/relationship/1"},"1h3rbp4":{"a":"recall","vg":"anat1-thorax-myology:e4/recall/1"},"y3xoov":{"a":"recall","vg":"anat1-thorax-myology:e4/recall/2"},"jmy58m":{"a":"recall","vg":"anat1-thorax-myology:e5/recall/1"},"1m7sq3":{"a":"recall","vg":"anat1-thorax-myology:e6/recall/1"},"iypekm":{"a":"recall","vg":"anat1-thorax-myology:e7/recall/1"},"zgc86b":{"a":"recall","vg":"anat1-thorax-myology:e8/recall/1"},"1vcrwnt":{"a":"recall","vg":"anat1-thorax-myology:e8/recall/1"},"1f53jmg":{"a":"recall","vg":"anat1-thorax-myology:e8/recall/1"},"ld2jri":{"a":"recall","vg":"anat1-thorax-myology:e7/recall/2"}},"explRev":"a69db2cce4bb"};
